        e = e / (np.linalg.norm(e, axis=1, keepdims=True) + 1e-9)
        centre = e.mean(axis=0)
        typical = e @ centre
        field = np.array([photos[i].get("kind", "field") != "specimen" for i in idx])
        pool = [j for j in range(len(idx)) if field[j]] or list(range(len(idx)))
